// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.LocationModeimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Location Handler (Module 10 v2 — Step 10.6, Review 1). * * Sets the device's location mode (GPS) — one of 4 modes per * [com.roshan.persona.brain.skill.LocationMode]: * *  - `HIGH_ACCURACY` — GPS + Wi-Fi + mobile network (most accurate, most battery) *  - `BATTERY_SAVING` — Wi-Fi + mobile network only (saves GPS battery) *  - `SENSORS_ONLY` — GPS only (no network assist) *  - `OFF` — location fully disabled * * ## Behavior (per strategy §"Privacy & Security — Location") * *  - **Direct toggle** (system app / rooted / ADB-granted WRITE_SECURE_SETTINGS): *    Writes to `Settings.Secure.LOCATION_MODE` directly. * *  - **Fallback** (regular app): Opens *    `Settings.ACTION_LOCATION_SOURCE_SETTINGS` page for manual toggle. * * ## Idempotent execution (Review 2 Elite 1) * * If the current location mode already matches the target, skip the toggle. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous location mode. Undo restores the actual previous mode. * * ## Resource category * * Location uses [ResourceCategory.CONNECTIVITY] — toggling it affects the * GPS radio, sequenced with other connectivity ops. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Location (Review 1)</a> */class LocationHandler(    private val locationService: LocationService,) : ReversibleHandler<SystemOperation.SetLocationMode> {    override val id: String = "location"    override val displayName: String = "Location Mode Control"    override val requiredPermissions: Set<String> = setOf(        android.Manifest.permission.ACCESS_FINE_LOCATION,        android.Manifest.permission.ACCESS_COARSE_LOCATION,    )    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = true  // all devices have location (GPS or network-based)    override suspend fun execute(operation: SystemOperation.SetLocationMode): Result<Unit> {        return try {            if (locationService.canToggleDirectly()) {                // System app / rooted / ADB — direct toggle.                val success = locationService.setMode(operation.mode)                if (success) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(                        error = AppError.Hardware.Unknown("location"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            } else {                // Regular app — open Settings page.                val launched = locationService.openSettingsPage()                if (launched) {                    Result.Success(                        data = Unit,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                        warnings = listOf("opened_settings_page"),                    )                } else {                    Result.Failure(                        error = AppError.Hardware.Unsupported("location_settings"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        } catch (t: Throwable) {            Timber.tag("LocationHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("location", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetLocationMode): Any? {        return try {            LocationPreState(previousMode = locationService.getMode())        } catch (t: Throwable) {            Timber.tag("LocationHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetLocationMode, preState: Any?) {        if (preState !is LocationPreState) return        try {            if (locationService.canToggleDirectly()) {                locationService.setMode(preState.previousMode)            } else {                Timber.tag("LocationHandler").i("Undo: location was ${preState.previousMode} — opening settings for manual restore.")                locationService.openSettingsPage()            }        } catch (t: Throwable) {            Timber.tag("LocationHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        LocationPreState(previousMode = locationService.getMode())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetLocationMode): Boolean {        return try {            locationService.getMode() == operation.mode        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetLocationMode): String =        when (operation.mode) {            LocationMode.HIGH_ACCURACY -> "Location set to high accuracy"            LocationMode.BATTERY_SAVING -> "Location set to battery saving"            LocationMode.SENSORS_ONLY -> "Location set to sensors only (GPS)"            LocationMode.OFF -> "Location turned off"        }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is LocationPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"LocationPreState\",\"previousMode\":\"${preState.previousMode.name}\"}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "LocationPreState" -> LocationPreState(                previousMode = LocationMode.valueOf((map["previousMode"] as? String) ?: "OFF"),            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for location (previous mode). */    data class LocationPreState(val previousMode: LocationMode)}
